//! Arginfo and method tables as Rust statics: the `zend_internal_arg_info[]`
//! arrays PHP's `gen_stub.php` writes as `ZEND_BEGIN_ARG_*`/`ZEND_ARG_*` macros
//! (one `const fn` per macro, computing the same `zend_type` from the headers'
//! own bits), and the `zend_function_entry[]` tables `PHP_ME` builds from them.
//! `crates/phpstubs` holds every stub's arginfo (generated by `tools/arginfo.py`); each
//! family declares its table with [`method_table!`].
use crate::sys::{
    _IS_BOOL, _ZEND_IS_VARIADIC_BIT, _ZEND_SEND_MODE_SHIFT, _ZEND_TYPE_ITERABLE_BIT,
    _ZEND_TYPE_LITERAL_NAME_BIT, _ZEND_TYPE_NULLABLE_BIT, IS_ITERABLE, IS_MIXED, MAY_BE_ANY,
    MAY_BE_BOOL, zend_execute_data, zend_function_entry, zend_internal_arg_info, zend_type, zval,
};
use std::{
    ffi::{CStr, c_char, c_void},
    ptr,
};

/// A stub's `zend_internal_arg_info[N]`: the return slot, then each parameter.
#[repr(transparent)]
pub struct ArgInfo<const N: usize>(pub [zend_internal_arg_info; N]);

// SAFETY: immutable static data; its pointers are to static strings.
unsafe impl<const N: usize> Sync for ArgInfo<N> {}

/// A `PHP_FE_END`-terminated `zend_function_entry[N]`, built only from
/// [`Entry`] rows, so each name before the end is a static C string.
#[repr(transparent)]
pub struct Methods<const N: usize>([zend_function_entry; N]);

// SAFETY: immutable static data; its pointers are to static strings, arginfo and
// handlers.
unsafe impl<const N: usize> Sync for Methods<N> {}

impl<const N: usize> Methods<N> {
    /// The table of `rows`.
    /// # Panics
    /// The last row isn't [`END`] (at compile time, for a static).
    #[must_use]
    pub const fn new(rows: [Entry; N]) -> Self {
        let mut table = [END.0; N];
        let (mut from, mut to): (&[Entry], &mut [zend_function_entry]) = (&rows, &mut table);
        while let (Some((row, rest)), Some((slot, slots))) =
            (from.split_first(), to.split_first_mut())
        {
            *slot = row.0;
            (from, to) = (rest, slots);
        }
        assert!(
            matches!(table.last(), Some(end) if end.fname.is_null()),
            "a method table ends with PHP_FE_END"
        );
        Self(table)
    }

    /// The table, for registration.
    #[must_use]
    pub const fn table(&'static self) -> Table {
        Table(&self.0)
    }

    /// The table without the rows named in `skip`, leaked for the process: for
    /// an upstream `#ifdef` only C++ can test, decided once at MINIT.
    #[must_use]
    pub fn without(&'static self, skip: &[&CStr]) -> Table {
        let keep = |row: &&zend_function_entry| {
            // SAFETY: a row's name is a static C string; only `END`'s is null.
            row.fname.is_null() || !skip.contains(&unsafe { CStr::from_ptr(row.fname) })
        };
        let rows: Vec<zend_function_entry> = self.0.iter().filter(keep).copied().collect();
        Table(Box::leak(rows.into_boxed_slice()))
    }
}

/// A method table as Zend registers it: a [`Methods`]' rows (or some of them,
/// or several joined), `PHP_FE_END` last, or none.
#[derive(Clone, Copy)]
pub struct Table(&'static [zend_function_entry]);

impl Table {
    /// No methods.
    pub const NONE: Self = Self(&[]);

    /// Each table's rows in turn, then one `PHP_FE_END`, leaked for the process.
    #[must_use]
    pub fn join(tables: &[Self]) -> Self {
        let mut rows: Vec<zend_function_entry> = tables
            .iter()
            .flat_map(|table| table.0.split_last().map_or(&[][..], |(_, rows)| rows))
            .copied()
            .collect();
        rows.push(END.0);
        Self(Box::leak(rows.into_boxed_slice()))
    }

    /// The table, as `INIT_CLASS_ENTRY` and `zend_register_functions` take it:
    /// null for none.
    #[must_use]
    pub const fn as_ptr(self) -> *const zend_function_entry {
        if self.0.is_empty() {
            ptr::null()
        } else {
            self.0.as_ptr()
        }
    }

    /// The rows, `PHP_FE_END` last, or none.
    pub(crate) const fn rows(self) -> &'static [zend_function_entry] {
        self.0
    }
}

/// A row of [`Methods`]: an [`entry`], or [`END`].
#[derive(Clone, Copy)]
pub struct Entry(zend_function_entry);

/// A Zend handler (`zif_handler`).
pub type Handler = unsafe extern "C" fn(*mut zend_execute_data, *mut zval);

/// `PHP_ME`/`ZEND_FE`/`ZEND_RAW_FENTRY`: `name`, run by `handler`, with `arginfo`.
#[must_use]
pub const fn entry<const N: usize>(
    name: &'static CStr,
    handler: Handler,
    arginfo: &'static ArgInfo<N>,
    flags: u32,
) -> Entry {
    let mut entry = definition(name, arginfo, flags);
    entry.handler = Some(handler);
    Entry(entry)
}

/// A function's immutable metadata before its native handler is lent at module load.
#[must_use]
pub const fn definition<const N: usize>(
    name: &'static CStr,
    arginfo: &'static ArgInfo<N>,
    flags: u32,
) -> zend_function_entry {
    let mut entry: zend_function_entry = crate::zeroed();
    entry.fname = name.as_ptr();
    entry.arg_info = arginfo.0.as_ptr();
    #[expect(
        clippy::cast_possible_truncation,
        reason = "arginfo has a handful of slots"
    )]
    {
        entry.num_args = (N - 1) as u32;
    }
    entry.flags = flags;
    entry
}

/// `PHP_FE_END`.
pub const END: Entry = Entry(crate::zeroed());

/// `_ZEND_ARG_INFO_FLAGS(send, variadic, 0)`.
const fn flags(send: u32, variadic: bool) -> u32 {
    (send << _ZEND_SEND_MODE_SHIFT) | if variadic { _ZEND_IS_VARIADIC_BIT } else { 0 }
}

/// `ZEND_TYPE_INIT_CODE`'s mask.
const fn code_mask(code: u32, nullable: bool) -> u32 {
    let mask = match code {
        _IS_BOOL => MAY_BE_BOOL,
        IS_ITERABLE => _ZEND_TYPE_ITERABLE_BIT,
        IS_MIXED => MAY_BE_ANY,
        code => 1 << code,
    };
    mask | if nullable { _ZEND_TYPE_NULLABLE_BIT } else { 0 }
}

const fn slot(
    name: *const c_char,
    ptr: *const c_char,
    mask: u32,
    default: Option<&'static CStr>,
) -> zend_internal_arg_info {
    zend_internal_arg_info {
        name,
        type_: zend_type {
            ptr: ptr.cast::<c_void>().cast_mut(),
            type_mask: mask,
        },
        default_value: match default {
            Some(value) => value.as_ptr(),
            None => ptr::null(),
        },
    }
}

/// The return slot's name field holds the required argument count.
const fn required(count: usize) -> *const c_char {
    ptr::without_provenance(count)
}

const fn literal(class: &'static CStr) -> *const c_char {
    class.as_ptr()
}

/// `ZEND_BEGIN_ARG_INFO_EX`.
#[must_use]
pub const fn begin(count: usize, by_ref: u32) -> zend_internal_arg_info {
    slot(required(count), ptr::null(), flags(by_ref, false), None)
}

/// `ZEND_BEGIN_ARG_WITH_RETURN_TYPE_INFO_EX`.
#[must_use]
pub const fn begin_type(
    count: usize,
    by_ref: u32,
    code: u32,
    nullable: bool,
) -> zend_internal_arg_info {
    slot(
        required(count),
        ptr::null(),
        code_mask(code, nullable) | flags(by_ref, false),
        None,
    )
}

/// `ZEND_BEGIN_ARG_WITH_RETURN_TYPE_MASK_EX`.
#[must_use]
pub const fn begin_mask(count: usize, by_ref: u32, mask: u32) -> zend_internal_arg_info {
    slot(
        required(count),
        ptr::null(),
        mask | flags(by_ref, false),
        None,
    )
}

/// `ZEND_BEGIN_ARG_WITH_RETURN_OBJ_INFO_EX`.
#[must_use]
pub const fn begin_class(
    count: usize,
    by_ref: u32,
    class: &'static CStr,
    nullable: bool,
) -> zend_internal_arg_info {
    let null = if nullable { _ZEND_TYPE_NULLABLE_BIT } else { 0 };
    slot(
        required(count),
        literal(class),
        _ZEND_TYPE_LITERAL_NAME_BIT | null | flags(by_ref, false),
        None,
    )
}

/// `ZEND_BEGIN_ARG_WITH_RETURN_OBJ_TYPE_MASK_EX`.
#[must_use]
pub const fn begin_class_mask(
    count: usize,
    by_ref: u32,
    class: &'static CStr,
    mask: u32,
) -> zend_internal_arg_info {
    slot(
        required(count),
        literal(class),
        _ZEND_TYPE_LITERAL_NAME_BIT | mask | flags(by_ref, false),
        None,
    )
}

/// `ZEND_ARG_INFO`, `ZEND_ARG_VARIADIC_INFO`, `ZEND_ARG_INFO_WITH_DEFAULT_VALUE`.
#[must_use]
pub const fn arg(
    name: &'static CStr,
    send: u32,
    variadic: bool,
    default: Option<&'static CStr>,
) -> zend_internal_arg_info {
    slot(name.as_ptr(), ptr::null(), flags(send, variadic), default)
}

/// `ZEND_ARG_TYPE_INFO` and its variadic and default-value forms.
#[must_use]
pub const fn arg_type(
    name: &'static CStr,
    send: u32,
    variadic: bool,
    code: u32,
    nullable: bool,
    default: Option<&'static CStr>,
) -> zend_internal_arg_info {
    slot(
        name.as_ptr(),
        ptr::null(),
        code_mask(code, nullable) | flags(send, variadic),
        default,
    )
}

/// `ZEND_ARG_TYPE_MASK`.
#[must_use]
pub const fn arg_mask(
    name: &'static CStr,
    send: u32,
    variadic: bool,
    mask: u32,
    default: Option<&'static CStr>,
) -> zend_internal_arg_info {
    slot(
        name.as_ptr(),
        ptr::null(),
        mask | flags(send, variadic),
        default,
    )
}

/// `ZEND_ARG_OBJ_INFO` and its variadic and default-value forms.
#[must_use]
pub const fn arg_class(
    name: &'static CStr,
    send: u32,
    variadic: bool,
    class: &'static CStr,
    nullable: bool,
    default: Option<&'static CStr>,
) -> zend_internal_arg_info {
    let null = if nullable { _ZEND_TYPE_NULLABLE_BIT } else { 0 };
    slot(
        name.as_ptr(),
        literal(class),
        _ZEND_TYPE_LITERAL_NAME_BIT | null | flags(send, variadic),
        default,
    )
}

/// `ZEND_ARG_OBJ_TYPE_MASK`.
#[must_use]
pub const fn arg_class_mask(
    name: &'static CStr,
    send: u32,
    variadic: bool,
    class: &'static CStr,
    mask: u32,
    default: Option<&'static CStr>,
) -> zend_internal_arg_info {
    slot(
        name.as_ptr(),
        literal(class),
        _ZEND_TYPE_LITERAL_NAME_BIT | mask | flags(send, variadic),
        default,
    )
}

/// A static `Methods` table, upstream's `PHP_ME` rows in upstream's order (the
/// order reflection lists them in), `PHP_FE_END` appended. A row under an
/// upstream `#ifdef` takes the matching `#[cfg]`:
///
/// ```ignore
/// method_table! {
///     static METHODS = [
///         c"lock" => zim_swoole_lock_lock, &lock::arginfo_class_Swoole_Lock_lock, ZEND_ACC_PUBLIC;
///         #[cfg(target_os = "linux")]
///         c"setAffinity" => zim_swoole_process_setAffinity, &process::arginfo_..., ZEND_ACC_PUBLIC;
///     ];
/// }
/// ```
#[macro_export]
macro_rules! method_table {
    (
        $vis:vis static $table:ident = [
            $($(#[$row:meta])* $name:literal => $handler:path, $arginfo:expr, $flags:expr;)*
        ];
    ) => {
        $vis static $table: $crate::arginfo::Methods<{ [$($(#[$row])* $name),*].len() + 1 }> =
            $crate::arginfo::Methods::new([
                $($(#[$row])* $crate::arginfo::entry($name, $handler, $arginfo, $flags),)*
                $crate::arginfo::END,
            ]);
    };
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::sys::{IS_LONG, IS_VOID, MAY_BE_FALSE, MAY_BE_LONG, MAY_BE_NULL};

    #[test]
    fn return_slot_holds_the_required_count() {
        let slot = begin_type(2, 0, IS_VOID, false);
        assert_eq!(slot.name as usize, 2, "required count");
        assert_eq!(slot.type_.type_mask, 1 << IS_VOID, "ZEND_TYPE_INIT_CODE");
        assert!(slot.default_value.is_null(), "no default");
    }

    #[test]
    fn codes_follow_zend_type_init_code() {
        assert_eq!(code_mask(_IS_BOOL, false), MAY_BE_BOOL, "bool");
        assert_eq!(code_mask(IS_MIXED, false), MAY_BE_ANY, "mixed");
        assert_eq!(
            code_mask(IS_ITERABLE, false),
            _ZEND_TYPE_ITERABLE_BIT,
            "iterable"
        );
        assert_eq!(code_mask(IS_LONG, true), MAY_BE_LONG | MAY_BE_NULL, "?int");
    }

    #[test]
    fn classes_are_literal_names() {
        let slot = arg_class_mask(c"ctx", 1, false, c"Foo\\Bar", MAY_BE_FALSE, Some(c"null"));
        assert_eq!(
            slot.type_.type_mask,
            _ZEND_TYPE_LITERAL_NAME_BIT | MAY_BE_FALSE | (1 << _ZEND_SEND_MODE_SHIFT),
            "by reference, class or false"
        );
        // SAFETY: the static literal passed above.
        let class = unsafe { CStr::from_ptr(slot.type_.ptr.cast()) };
        assert_eq!(class, c"Foo\\Bar", "class name");
    }

    #[test]
    fn variadic_sets_its_bit() {
        let slot = arg(c"args", 0, true, None);
        assert_eq!(
            slot.type_.type_mask, _ZEND_IS_VARIADIC_BIT,
            "variadic, untyped"
        );
    }
}
